import{_ as n,l,o as e,c as o,v as t,p as s,x as r,d as g,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"不平等与 r > g","description":"","frontmatter":{"title":"不平等与 r > g","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/inequality-r-g.md","filePath":"econ/inequality-r-g.md","lastUpdated":1789023840000}'),E={name:"econ/inequality-r-g.md"};function c(h,a,m,u,A,_){const i=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="不平等与-r-g" tabindex="-1">不平等与 r &gt; g <a class="header-anchor" href="#不平等与-r-g" aria-label="Permalink to &quot;不平等与 r &gt; g&quot;">​</a></h1><div class="epigraph"><p>若资本回报持久地高于经济增长，已有财富相对劳动收入膨胀；但这是会计加机制的候选，不是一条无价格的自然律。</p><footer>—— Piketty, Capital in the Twenty-First Century, 2014；Krusell and Smith 对 $r-g$ 的一般均衡评论；Piketty and Zucman, Capital is Back, QJE 2014</footer></div><p><a href="/econ/fiscal-hank">上一课</a>的刺激是短期再分配。长期顶层份额的运动常被写成 \\(r\\gt g\\)。本课缺口是把这句话接到<strong>已经写过的</strong>内生 \\(r\\)（Aiyagari、尾、公债）上，而不是当口号。不重写一次总付乘数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Piketty：财富/收入比 \\(\\beta=s/g\\)（稳态），资本份额 \\(\\alpha=r\\beta\\)。\\(r\\gt g\\) 时遗产与资本收入相对工资膨胀，顶层份额升。会计成立。一般均衡：储蓄率、价格、\\(r\\) 都会对 \\(\\beta\\) 的上升起反应；Krusell–Smith 提醒不能把 \\(r\\) 当外生。缺口是：在不完全市场模型里，\\(r-g\\) 由什么决定，它何时足以解释尾与份额，何时必须靠收益异质（上一课尾）。</p><p><span class="marginnote">Piketty, 2014。Piketty and Zucman, <em>QJE</em> 2014。Jones 对 \\(r-g\\) 与帕累托的增长理论对照。Acemoglu–Robinson 对制度的批评。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在 Aiyagari–KS 里改变 \\(\\beta\\)、\\(g\\)、资本税、利润份额，看 \\(r\\) 与财富份额。开放经济小国：\\(r\\) 更外生，\\(r\\gt g\\) 的力量更大。封闭经济：\\(K\\) 上升压 \\(r\\)，自我限制。住房与土地：不可再生要素使 \\(\\beta\\) 可升而 \\(r\\) 不必等于资本边际产出。测量：\\(r\\) 是哪一个——权益、住房、全部财富的加权，口径决定不等式。</p>',8)),(e(),s(p,null,{default:r(()=>[d(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACC%5B%22%E4%BC%9A%E8%AE%A1%3A%20%CE%B2%20%E2%89%88%20s%2Fg%22%5D%20--%3E%20SHARE%5B%22%E8%B5%84%E6%9C%AC%E4%BB%BD%E9%A2%9D%22%5D%0A%20%20RG%5B%22r%3Eg%22%5D%20--%3E%20TAIL%5B%22%E9%A1%B6%E5%B1%82%E8%86%A8%E8%83%80%22%5D%0A%20%20GE%5B%22%E5%86%85%E7%94%9F%20r%22%5D%20--%3E%20LIM%5B%22%E5%B0%81%E9%97%AD%E7%BB%8F%E6%B5%8E%E8%87%AA%E6%88%91%E9%99%90%E5%88%B6%22%5D%0A%20%20HET%5B%22%E6%94%B6%E7%9B%8A%E5%BC%82%E8%B4%A8%22%5D%20--%3E%20TAIL%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[g(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>增长下降（\\(g\\) 降）在会计上抬 \\(\\beta\\)，与「储蓄率故事」不同。本课两者都保留，不选边当唯一。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是相对增长。劳动收入随 \\(g\\) 增；已投资本按 \\(r\\) 滚。再分配、累进税、战争摧毁、住房价格，是历史里打断 \\(r\\gt g\\) 的力量。HANK 的短期 MPC 加权与长期 \\(r\\gt g\\) 不是同一时间尺度：支票改的是季度 \\(C\\)，资本积累改的是十年份额。把二者塞进同一 IRF 会乱。</p><p>金融摩擦单元会让 \\(r\\) 含风险与中介利差，名义 \\(r\\) 与资本净回报再分叉——本课先用实物 \\(r\\)。</p><p><span class="marginnote">\\(r\\gt g\\) 作为庞氏或债务可持续条件，在后课 \\(r-g\\) 与主权债里以公共部门再出现。私人财富与公债不是同一个 \\(r\\)。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写最优财富税税率表。不预测未来三十年基尼。不把文学性的「二十一世纪」当计量结果。公司金融的治理与股票回购不是这里的 \\(r\\)。</p><p>后课默认：\\(r\\gt g\\) 是放大已有财富的候选机制，必须与内生 \\(r\\) 和收益异质一起读。下一课：截面不仅是财富，还有代际的人力资本流动。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(r\\gt g\\) 的会计清楚；一般均衡里 \\(r\\) 会动。</li><li>封闭经济有自我限制；开放与土地弱化限制。</li><li>尾仍常需收益异质，不只平均 \\(r-g\\)。</li><li>出处：Piketty 2014；Piketty and Zucman, <em>QJE</em> 2014；Krusell–Smith 评论。</li></ul>',10))])}const b=n(E,[["render",c]]);export{f as __pageData,b as default};
